@model Umbraco.Bench.Umbraco.Models.Blocks.ArticleModel

<article class="space-y-8">
    <header class="space-y-4">
        <p class="text-sm font-semibold uppercase tracking-[0.22em] text-cyan-300">MCP field note</p>
        <h1 class="max-w-3xl text-4xl font-bold tracking-tight text-white sm:text-6xl">@Model.Heading</h1>
        <p class="max-w-2xl text-xl leading-8 text-slate-300">@Model.Intro</p>
    </header>
    @if (Model.ImageUrl is not null)
    {
        <figure class="overflow-hidden rounded-2xl border border-white/10 bg-slate-900">
            <img class="aspect-[16/9] w-full object-cover" src="@Model.ImageUrl" alt="@Model.ImageAlt" />
            @if (!string.IsNullOrWhiteSpace(Model.ImageCaption))
            {
                <figcaption class="px-4 py-3 text-sm text-slate-400">@Model.ImageCaption</figcaption>
            }
        </figure>
    }
    <div class="max-w-3xl space-y-5 text-lg leading-8 text-slate-200">
        @Html.Raw(Model.BodyHtml)
    </div>
</article>
