@model Umbraco.Bench.Umbraco.Models.Blocks.PostListingModel

<section class="space-y-10">
    <header class="max-w-3xl space-y-4">
        <p class="text-sm font-semibold uppercase tracking-[0.22em] text-cyan-300">Model Context Protocol</p>
