            <a class="group rounded-2xl border border-white/10 bg-white/[0.03] p-7 transition hover:-translate-y-1 hover:border-cyan-300/50 hover:bg-cyan-300/[0.06]" href="@post.Url">
                <p class="mb-8 text-sm font-medium text-cyan-300">Read field note →</p>
                <h2 class="text-2xl font-semibold tracking-tight text-white group-hover:text-cyan-100">@post.Title</h2>
            </a>
        }
    </div>
</section>
